import { createHash } from "node:crypto";
import { lstat, readFile, rm } from "node:fs/promises";
import { join, resolve } from "node:path";

export const CATALOG_GENERATED_HEADER =
  "// Generated by pnpm catalog:generate. Edit captured facts or grammar policy, not this file.\n";
export const catalogOutputDigest = (bytes) => `sha256:${createHash("sha256").update(bytes).digest("hex")}`;

/** Ownership comes from the emitter manifest; no grammar/version or semantic-facet allowlist. */
export function isCatalogProjection(path) {
  return (
    typeof path === "string" &&
    /^packages\/[^/]+\/src\/.+\.ts$/u.test(path) &&
    !path.includes("\\") &&
    path.split("/").every((part) => part !== "" && part !== "." && part !== "..")
  );
}
export async function assertProjectionPath(root, path) {
  if (!isCatalogProjection(path)) throw new TypeError(`Invalid catalog projection path: ${path}`);
  let current = resolve(root);
  for (const part of path.split("/")) {
    current = join(current, part);
    try {
      if ((await lstat(current)).isSymbolicLink())
        throw new Error(`Catalog projection path contains a symbolic link: ${path}`);
    } catch (error) {
      if (error.code === "ENOENT") break;
      throw error;
    }
  }
}
export async function readCatalogManifest(root) {
  let bytes;
  try {
    bytes = await readFile(join(root, "grammar/catalog/generation.json"));
  } catch (error) {
    if (error.code === "ENOENT") return undefined;
    throw error;
  }
  const manifest = JSON.parse(bytes.toString("utf8"));
  if (
    manifest.formatVersion !== 1 ||
    !Array.isArray(manifest.outputs) ||
    manifest.outputs.some((path) => typeof path !== "string") ||
    manifest.outputDigestFormat !== "utf8-bytes-sha256" ||
    typeof manifest.outputDigests !== "object" ||
    manifest.outputDigests === null
  )
    throw new TypeError("Invalid catalog ownership manifest");
  return manifest;
}
/** Inspect all candidates before removing any; altered or symlinked projections are never deleted. */
export async function ownedCatalogProjections(root, manifest, include = () => true) {
  const files = [];
  for (const path of [...new Set(manifest?.outputs ?? [])]) {
    if (!isCatalogProjection(path) || !include(path)) continue;
    await assertProjectionPath(root, path);
    let bytes;
    try {
      bytes = await readFile(join(root, path));
    } catch (error) {
      if (error.code === "ENOENT") continue;
      throw error;
    }
    if (
      !bytes.subarray(0, Buffer.byteLength(CATALOG_GENERATED_HEADER)).equals(Buffer.from(CATALOG_GENERATED_HEADER)) ||
      catalogOutputDigest(bytes) !== manifest.outputDigests[path]
    )
      throw new Error(`Catalog projection changed; refusing removal: ${path}`);
    files.push(path);
  }
  return files;
}
export async function cleanCatalogProjections(root) {
  const paths = await ownedCatalogProjections(root, await readCatalogManifest(root));
  for (const path of paths) await rm(join(root, path));
  return paths;
}
